import functools

def natural_sort_strings(items):
    def _key(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j].isdigit():
                j += 1
            if j > i:
                tokens.append(('num', int(s[i:j])))
                i = j
            else:
                tokens.append(('text', s[i:j]))
                i = j
        return tokens

    @functools.cmp_to_key
    def _compare(a, b):
        ka = _key(a)
        kb = _key(b)
        len_a = len(ka)
        len_b = len(kb)
        min_len = len_a if len_a < len_b else len_b
        for idx in range(min_len):
            ta = ka[idx]
            tb = kb[idx]
            if ta[0] != tb[0]:
                return -1 if ta[0] == 'text' else 1
            if ta[1] < tb[1]:
                return -1
            elif ta[1] > tb[1]:
                return 1
        if len_a != len_b:
            return -1 if len_a < len_b else 1
        return 0

    return sorted(items, key=functools.cmp_to_key(_compare))

